const n=[{id:"M01",title:"Wang, Wang & Gai · 2021 · Mentales Kontrastieren mit Wenn-dann-Plänen",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 unabhängige Effekte aus 21 Artikeln, 15.907 Teilnehmende: ein kleiner durchschnittlicher Vorteil beim Erreichen von Zielen, g = 0,336 [0,229; 0,443]. Nach Korrektur möglicher Publikationsverzerrung lag die Schätzung bei 0,242 [0,143; 0,342].",limitation:"Die Ergebnisse unterschieden sich deutlich; es gab Hinweise auf Publikationsverzerrung. Dieser Kurs und seine kurzen Übungen wurden nicht untersucht. Ergebnisse sind nicht garantiert."},{id:"M02",title:"Gollwitzer & Sheeran · 2006 · Wenn-dann-Pläne und das Erreichen von Zielen",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 unabhängige Tests mit 8.461 Teilnehmenden: konkrete Wenn-dann-Pläne halfen im Durchschnitt beim Erreichen von Zielen, d = 0,65 [0,60; 0,70].",limitation:"Ältere, uneinheitliche Studien, nicht durchgängig vorab registriert. Ein Plan macht Anstrengung, Erinnern, praktische Grenzen und Unsicherheit nicht überflüssig."},{id:"M03",title:"Harkin et al. · 2016 · Fortschritte auf dem Weg zum Ziel festhalten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 Experimente mit insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen: d = 0,40 [0,32; 0,48]. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien ergab 0,19 [0,10; 0,28].",limitation:"Ziele und Methoden waren unterschiedlich. Zusammenhänge mit Studienmerkmalen verpflichten nicht zum öffentlichen Teilen. Dieses genaue Protokoll, die Rückblicktermine und der ODA-Kurs wurden nicht validiert."},{id:"M04",title:"Cole et al. · 2021 · Handlungen gedanklich durchspielen und Verhalten ändern",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 Studien, 123 Effekte, 5.685 Teilnehmende: insgesamt g = 0,49 [0,37; 0,62] für gedankliches Durchspielen. Der Gesamttest zum Vergleich der einzelnen Formen war statistisch nicht signifikant.",limitation:"Meist Studierende und unterschiedliche Übungen. Für reine Ablaufvorstellungen lagen fünf Effekte mit unklarer Schätzung vor. Keine verlässliche Rangfolge der Formen; diese kurze Übung wurde nicht validiert."},{id:"M07",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Glaube an Manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Drei US-Onlinebefragungen mit 1.023 Teilnehmenden: Manifestationsglaube hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, aber nicht mit selbst berichtetem Einkommen oder Bildungsstand.",limitation:"Zusammenhänge belegen keine Ursache und prüfen nicht jede Manifestationstechnik objektiv. Selbst berichtete finanzielle Ergebnisse sagen die Zukunft einer einzelnen Person nicht voraus."},{id:"M10",title:"Gollwitzer & Brandstätter · 1997 · Eine konkrete Gelegenheit zum Anfangen planen",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"In Studie 2 sollten 86 Studierende einen Bericht schreiben. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12/17 mit Plan und 6/19 in der Kontrollgruppe innerhalb von zwei Tagen.",limitation:"71 % gegenüber 32 % betrifft die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. Eng begrenzte Studienaufgabe; der ODA-Kurs wurde nicht validiert."},{id:"M11",title:"Oettingen et al. · 2015 · Planung und Termine im Kalender",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Studie 1 wertete 84 Studierende aus. Der vorab geplante Vergleich fiel bei eingeplanten Stunden zugunsten von mentalem Kontrastieren plus Wenn-dann-Plänen aus, p = 0,03; Gesamttest p = 0,057.",limitation:"Gemessen wurde geplante Zeit, keine erledigte Arbeit oder Produktivität. Unvollständige Antworten wurden ausgeschlossen. Die kurze Kursfassung und ihre Einteilung praktischer Bedingungen wurden nicht untersucht."},{id:"M14",title:"NIMH · Hilfe bei psychischen Erkrankungen",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Die offizielle Orientierung zeigt Wege zu fachlicher Unterstützung und Krisenhilfe bei Belastung, Beeinträchtigung oder unmittelbarer Gefahr.",limitation:"Eine Orientierung, keine Wirksamkeitsstudie. ODA diagnostiziert oder behandelt keine psychischen Erkrankungen. Außerhalb der USA nutze die örtlichen Behandlungsangebote und Notdienste."},{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Idealisierte positive Zukunftsfantasien",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Vier Experimente, überwiegend mit Studierenden, fanden nach manchen idealisierten positiven Fantasien unmittelbar weniger Energie. Studie 3 verglich positive mit neutralen oder ungelenkten Fantasien, nicht mit hinterfragenden Fantasien.",limitation:"Kleine, kurze Experimente. Optimismus und Vorstellungskraft sind nicht grundsätzlich schädlich. Weder eine wiederkehrende Fantasieschleife noch ein Gehirnsignal für bereits erreichte Ziele wurde gemessen."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Glaube an Manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden fanden Zusammenhänge von Manifestationsglaube mit Zuversicht und einigen selbst berichteten finanziellen Risiken, darunter Insolvenzen. Kein Zusammenhang mit selbst berichtetem Einkommen oder Bildungsstand.",limitation:"Zusammenhänge belegen keine Ursache und prüfen nicht jede Technik objektiv. Selbst berichtete Ergebnisse sind keine Vorhersage für eine einzelne Person."},{id:"manifest-murphy",title:"Joseph Murphy · Die Macht Ihres Unterbewusstseins · Herkunft laut Verlag",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Der Verlag beschreibt Murphys bekanntes Selbsthilfebuch und seine Lehren über Vorstellungskraft und Glauben.",limitation:"Verlagsbeschreibung, keine kontrollierte Studie. Die genauen Passagen zum Abendritual wurden nicht überprüft. Hier gibt es keine Belege für das Anziehen von Reichtum, Heilung oder besonders wirksames Lernen vor dem Schlafen."}],e=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"de",title:"Dein Traum wartet? Mach heute etwas Brauchbares",goal:"Erarbeite einen brauchbaren Teil für ein Ziel, das du selbst wählst.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Wieder eine Woche vom anderen Leben geträumt? Mach aus einem Wunsch heute etwas, das du nutzen kannst.",reason:{id:"manifest-1-reason",label:"Wessen Ziel ist das, und wofür lohnt sich deine Zeit?",kind:"text",maxLength:160,optional:!0,suggestions:["Mein Ziel; abends scrollen kann warten","Familie geht vor; Feinschliff kann warten","Das Ziel anderer; Zeit dafür überdenken","Ich weiß nicht, wessen Ziel das ist"]},why:{id:"manifest-1-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein besserer Job ist ein Ergebnis. Einen Satz im Lebenslauf zu verbessern ist eine Handlung. Ob jemand dich anruft, entscheiden weiterhin andere. Mach etwas, das sich lohnt. Miss deinen Einsatz nicht an der erhofften Antwort.","In einem Experiment mit Studierenden half ein festgelegter Start mit Zeit und Ort, einen Bericht rechtzeitig zu schreiben. Das galt für jene, die ihn zurückschickten. Die Mitarbeit insgesamt nahm nicht zu. Ein Plan kann beim Anfangen helfen, garantiert aber kein Ergebnis. Erarbeite heute einen brauchbaren Satz, eine Antwort oder eine Bitte. Bleib im Kurs bei diesem Ziel und komm mit dem zurück, was passiert ist."],example:{title:"Daniel fängt an",text:"Nach dem Abendessen setzt Daniel sich für zehn Minuten an den Küchentisch. Er sucht einen Logistikjob. Im Lebenslauf beschreibt er neu, wie er acht Lagerschichten geplant hat. Der Satz klingt noch holprig. Trotzdem speichert er ihn und notiert die Änderung. Ein Arbeitgeber hat ihn noch nicht gesehen. Morgen kann Daniel einen echten Entwurf verbessern."}},move:{invitation:"Wähle deine Handlung. Die Vorschläge zeigen Daniels Lebenslauf.",instructions:["Benenne vor dem Speichern das Dokument, die Frage oder den Gegenstand, den du veränderst.","Erledige dein Minimum. Halte es getrennt von einer Antwort anderer fest."],prompts:[],suggestions:{action:["Einen Lebenslaufsatz zur Schichtplanung neu schreiben","Nach einer fehlenden Angabe im Lebenslauf fragen","Eine Arbeitsprobe zur Besetzung von Schichten erstellen"],minimum:["Einen Lebenslaufsatz zur Schichtplanung speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Eine Arbeitsprobe zur Besetzung von Schichten speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn das Abendessen abgeräumt ist","Wenn die Mittagspause zu Ende ist","Nach meinem Getränk am Morgen"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Dokument mit meinem Lebenslauf"],minutes:[10,2,5],fallback:["Eine Schichtänderung in einfachen Worten beschreiben","Eine andere freie Gelegenheit auswählen und benennen","In der Bibliothek nach Computerzugang fragen"],observation:["Den Lebenslaufsatz, den ich gespeichert habe","Ob ich die Lebenslauffrage abgeschickt habe","Was mich an meinem Minimum gehindert hat"]},suggested:{action:"Einen Lebenslaufsatz zur Schichtplanung neu schreiben",minimum:"Einen Lebenslaufsatz zur Schichtplanung speichern",minutes:10,cueHint:"Wenn das Abendessen abgeräumt ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich habe weniger Zeit als geplant",fallbackHint:"Eine Schichtänderung in einfachen Worten beschreiben",observationHint:"Den Lebenslaufsatz, den ich gespeichert habe"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Pausiere Schritte, die unsicher oder nicht bezahlbar sind. Suche stattdessen praktische Unterstützung."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniel hat eine passende Stelle gefunden und zehn Minuten vor dem Abendessen. Sein Lebenslauf beschreibt die gefragte Erfahrung mit der Schichtplanung noch nicht.",question:"Was wäre der sinnvollste erste Versuch?",options:[{id:"manifest-1-research-more",text:"Weitere Stellen vergleichen, um zu prüfen, ob dieser Job wirklich zu seinem gewünschten Leben passt.",feedback:"Stellen zu vergleichen kann ein Ziel klären. Diese Stelle passt bereits. Was fehlt, ist eine brauchbare Beschreibung von Daniels Erfahrung. Verbessere diesen Satz in der verfügbaren Zeit."},{id:"manifest-1-improve-line",text:"Einen Lebenslaufsatz für diese Stelle überarbeiten, den Entwurf speichern und notieren, was noch Arbeit braucht.",feedback:"So entsteht in zehn Minuten etwas, das Daniel nutzen kann. Der Entwurf braucht vielleicht Rückmeldung, und der Arbeitgeber antwortet womöglich nicht. Beides macht die geleistete Arbeit nicht ungeschehen."},{id:"manifest-1-clarify-future",text:"Seinen idealen Arbeitstag genau beschreiben und erst danach entscheiden, was er in den Lebenslauf schreibt.",feedback:"Der gewünschte Arbeitstag kann später bei Entscheidungen helfen. Daniel hat schon eine passende Stelle gewählt. Mehr Beschreibung verschiebt die konkrete Lücke. Schreibe den Lebenslaufsatz und prüfe dann, was noch fehlt."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Mach aus dem Wunsch eine Handlung. Halte sie getrennt von der erhofften Antwort fest.",followUp:{questionId:"manifest-1-return",question:"Was kannst du nach deinem Versuch jetzt tatsächlich nutzen?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Wobei ein Plan zum Anfangen helfen kann",paragraphs:["In ihrer Studie 2 von 1997 ließen Gollwitzer und Brandstätter 86 Münchner Studierende einen Bericht über Weihnachten schreiben. Die Planungsgruppe wählte eine genaue Zeit und einen Ort, stellte sich diese Gelegenheit vor, nahm sich vor, dort anzufangen, und hielt die Entscheidungen fest. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12 von 17 mit Plan und sechs von 19 in der Kontrollgruppe innerhalb der geforderten zwei Tage. Diese Anteile betreffen die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. [M10]","Diese Lektion übernimmt die konkrete Gelegenheit und verbindet sie mit brauchbarer Arbeit. Diese Übertragung auf andere Aufgaben wurde in der Weihnachtsbericht-Studie nicht geprüft. Ein Datum allein sagt dir noch nicht, woher die Zeit kommen soll. Wähle ein Ereignis, das du erkennst, und einen Ort, den du erreichen kannst. Fehlen nötige Mittel, kann es der passende Schritt sein, danach zu fragen. Halte diese Bitte als Bitte fest, auch wenn die Hilfe noch nicht da ist."]},{heading:"Dein Wunsch steuert keine anderen Menschen",paragraphs:["Wang und Kollegen fassten 2021 in einer Übersichtsarbeit 24 unabhängige Effekte aus 21 Artikeln mit 15.907 Teilnehmenden zusammen. Ein gewünschtes Ergebnis mit einem Hindernis und einer Wenn-dann-Reaktion zu verbinden, brachte im Durchschnitt einen kleinen Vorteil bei der Zielerreichung: g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Die Ergebnisse unterschieden sich deutlich. Eine Korrektur möglicher Publikationsverzerrung senkte die Schätzung. Das stützt Planung innerhalb ihrer Grenzen, aber kein Erfolgsversprechen für diesen Kurs. [M01]","Dixon und Kollegen untersuchten Manifestationsglauben in drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden. Er hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, nicht mit selbst berichtetem Einkommen oder Bildungsstand. Diese Zusammenhänge belegen nicht, dass der Glaube Insolvenzen verursacht hat. Sie prüfen auch nicht jede Manifestationsübung objektiv. [M07] Nutze deinen Wunsch, um eine Aufgabe zu wählen und Grenzen zu prüfen. Schließe daraus nicht, dass Gedanken eine Gelegenheit angezogen oder Not verursacht haben. Du hast dir ein Ergebnis auch nicht durch Gedanken verdient. Geld, Sorgearbeit, Zugang und die Entscheidungen anderer bleiben relevant."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"de",title:"Wieder nur geübt? Bring den Satz aufs Papier",goal:"Übe eine schwierige Stelle im Kopf. Erarbeite dann den nächsten brauchbaren Teil deiner bisherigen Aufgabe.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"Das fertige Wunschleben kannst du dir leicht vorstellen. Was passiert, wenn die Seite vor dir leer ist?",reason:{id:"manifest-2-reason",label:"Hilft eine weitere Probe, oder ersetzt sie den tatsächlichen Versuch?",kind:"text",maxLength:160,optional:!0,suggestions:["Sie zeigt mir eine fehlende Anweisung","Sie verzögert das Schreiben eines fertigen Satzes","Ich habe noch keine Probe festgehalten"]},why:{id:"manifest-2-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hol deine Aufgabe und vorhandene Notizen hervor. Im Kopf zu üben bedeutet, eine bestimmte Handlung gedanklich auszuführen, etwa den ersten Satz zu sagen. Schritte aufzulisten ist eine andere Art der Vorbereitung. Beides ist noch kein tatsächlicher Versuch.","Eine Übersichtsarbeit fand im Durchschnitt Vorteile für das Verhalten durch gedankliches Durchspielen. Eine beste Form war nicht belegt. Das beweist nicht, dass diese kurze Probe wirkt. Nutze sie, um deine schwierige Stelle und eine mögliche Reaktion zu erkennen. Beschreibe die Handlung in Worten, wenn keine Bilder kommen. Schreibe danach den nächsten brauchbaren Satz für dieselbe Aufgabe."],example:{title:"Daniel vor der leeren Zeile",text:"Nach dem Abendessen öffnet Daniel seinen Lebenslauf wieder. Dreißig Sekunden lang übt er im Kopf, eine schwierige Schichtänderung zu beschreiben. Er erwartet, ins Stocken zu geraten, und probt: „Acht Schichten umgeplant, als …“ Dann tippt er einen brauchbaren Satz. Er streicht zwei Wörter und notiert eine Rückfrage. Wie viele Details nötig sind, hatte seine Probe nicht gezeigt."},rehearsal:{label:"Freiwillige Vorbereitung",steps:["Beschreibe den nächsten Schritt und eine Stelle, an der du wahrscheinlich hängen bleibst.","Übe deine erste Reaktion einmal im Kopf. Das ist Vorbereitung."]}},move:{invitation:"Bleib bei deiner Aufgabe. Passe die Lebenslaufbeispiele an.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei. Geh die schwierige Stelle an.","Ohne Plan: Benenne vor dem Speichern deine Handlung und eine verfügbare Gelegenheit.","Übe einmal, dann handle. Nur im Kopf zu üben bleibt Vorbereitung."],prompts:[],suggestions:{action:["Kurz üben, dann einen Satz zur Schichtplanung schreiben","Im Kopf üben, dann nach einer Lebenslaufangabe fragen","Mit schriftlichen Schritten ein Datum im Lebenslauf berichtigen"],minimum:["Nach der Probe einen Lebenslaufsatz speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Ein berichtigtes Datum im Lebenslauf speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn das Abendessen abgeräumt ist","Wenn die Mittagspause zu Ende ist","Wenn ich das Dokument mit meinem Lebenslauf öffne"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Dokument mit meinem Lebenslauf"],minutes:[5,2,10],fallback:["Die Probe beenden; eine echte Schichtänderung aufschreiben","Ohne Bilder arbeiten; den ersten schriftlichen Schritt nutzen","Nachfragen, welche Angabe im Lebenslauf fehlt"],observation:["Was die Probe bei der Handlung übersehen hat","Den Lebenslaufsatz, den ich tatsächlich erarbeitet habe","Ob ich nur im Kopf geübt habe"]},suggested:{action:"Kurz üben, dann einen Satz zur Schichtplanung schreiben",minimum:"Nach der Probe einen Lebenslaufsatz speichern",minutes:5,cueHint:"Wenn das Abendessen abgeräumt ist",placeHint:"An meinem Küchentisch",obstacleHint:"Ich feile an der Probe, statt anzufangen",fallbackHint:"Die Probe beenden; eine echte Schichtänderung aufschreiben",observationHint:"Was die Probe bei der Handlung übersehen hat"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Wenn dich Planen im Bett wach hält, hör auf und nutze eine Gelegenheit tagsüber."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniel kann seinen ersten Lebenslaufsatz schon formulieren. Das Dokument ist bereit. Trotzdem möchte er die ganze Bewerbung noch einmal im Kopf durchgehen.",question:"Welcher nächste Schritt hilft bei diesem Versuch?",options:[{id:"manifest-2-full-rehearsal",text:"Die ganze Bewerbung noch einmal im Kopf durchgehen, um den besten Einstieg zu wählen, bevor er etwas schreibt.",feedback:"Eine vollständige Probe kann spätere Arbeit vorbereiten. Daniel hat aber schon einen brauchbaren Einstieg und das Dokument vor sich. Noch ein Durchlauf verschiebt den verfügbaren Versuch. Tippe den Satz und prüfe ihn."},{id:"manifest-2-new-goal-scene",text:"Sich den ersten Arbeitstag im neuen Job vorstellen, um neue Motivation zu finden, und später zur Bewerbung zurückkehren.",feedback:"Der vorgestellte Job kann zeigen, warum er dir wichtig ist. Er prüft Daniels vorbereiteten Einstieg aber nicht. Nutze den Satz jetzt im Dokument. Schau danach, was schwieriger war als erwartet."},{id:"manifest-2-perform-opening",text:"Den ersten Satz einmal im Kopf üben, in den Entwurf tippen und die tatsächliche Schwierigkeit mit der Erwartung vergleichen.",feedback:"So unterstützt die Vorbereitung eine echte Handlung. Daniel hat einen getippten Satz, den er prüfen kann. Qualität und Unbehagen bleiben offene Fragen. Beides entscheidet nicht darüber, ob der Versuch zählt."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"Lass auf hilfreiche Vorbereitung eine echte Handlung folgen. Halte beides getrennt fest.",followUp:{questionId:"manifest-2-return",question:"Was war beim tatsächlichen Schritt anders als bei der Probe?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Was sich aus der Forschung zum Durchspielen vergleichen lässt",paragraphs:["Cole und Kollegen fassten 2021 in einer Übersichtsarbeit 94 Studien, 123 Effekte und 5.685 Teilnehmende zusammen. Gedankliches Durchspielen zeigte insgesamt einen Verhaltenseffekt von g = 0,49, mit einem 95%-Konfidenzintervall von 0,37 bis 0,62. Meist waren die Teilnehmenden Studierende. Inhalt, Umfang und gemessene Ergebnisse der Übungen unterschieden sich. Der Durchschnitt sagt daher nicht voraus, was deine kurze Übung bewirkt. [M04]","Die Übersichtsarbeit unterschied zwischen dem Durchdenken von Ablaufschritten und dem gedanklichen Ausführen einer Aufgabe. Die Schätzung für reine Ablaufvorstellungen beruhte auf fünf Effekten; ihr Konfidenzintervall umfasste auch den Wert für keinen Effekt. Der Gesamtvergleich der Formen war statistisch nicht signifikant. Höhere Durchschnittswerte einzelner Gruppen belegen deshalb keinen verlässlichen Sieger. Eine Grafik ist kein Auftrag, intensiver zu visualisieren. Diese Lektion nutzt die Probe, um ein praktisches Detail sichtbar zu machen. Danach versuchst du die Aufgabe. Eine Beschreibung in Worten bietet einen zugänglichen Weg. Das bedeutet nicht, dass ihre Gleichwertigkeit mit Bildern wissenschaftlich belegt wäre."]},{heading:"Bereite eine Gelegenheit vor und nutze sie dann",paragraphs:["Im ursprünglichen Experiment zur Berichtsplanung stellten sich die Teilnehmenden eine konkrete Zeit und einen Ort zum Anfangen vor. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende und eine eng begrenzte Studienaufgabe. Daraus folgt weder ein allgemeines Vorstellungsskript noch ein Vorteil von Proben im Bett. [M10] Hier ist Vorbereitung dann sinnvoll, wenn sie dir beim nächsten Teil deiner bisherigen Aufgabe hilft.","Vielleicht bemerkst du ein fehlendes Passwort, eine unklare Anweisung oder einen Satz, den du noch nicht erklären kannst. Ein Passwort zurückzusetzen ist Vorbereitung. Benötigte Angaben abzusenden ist Arbeit an der Aufgabe. Zeig diesen Unterschied in deinen Notizen. Hör mit Planung vor dem Schlafen auf, wenn sie dich wach hält, und plane stattdessen tagsüber. Das ist eine praktische Anpassung für diesen Kurs. Die kurze Probe ist freiwillig. Sie ist weder ein validiertes Ritual noch eine Voraussetzung zum Anfangen. Du brauchst kein lebhaftes Bild und kein bestimmtes Gefühl."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"de",title:"Das Hindernis ist echt. Ändere die Bedingungen",goal:"Nutze deinen letzten Versuch, um eine machbare Reaktion auf ein Hindernis zu wählen und auszuprobieren.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Kinderbetreuung, fehlender Zugang oder Erschöpfung stehen im Weg? Mehr Glaube schafft keine freien Stunden im Tag.",reason:{id:"manifest-3-reason",label:"Wo brauchst du Hilfe, und was kannst du jetzt ändern?",kind:"text",maxLength:160,optional:!0,suggestions:["Laptop teilen; Nutzung gemeinsam absprechen","Ich kann die Lebenslaufarbeit verkleinern","Sorgearbeit lässt heute keine Gelegenheit frei","Mir ist noch kein Hindernis begegnet"]},why:{id:"manifest-3-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Nutze dein Ziel und vorhandene Notizen. Ohne Versuch: Benenne ein wahrscheinliches Hindernis. „Abends ist der gemeinsame Computer belegt“ hilft, eine Reaktion zu finden. „Mir fehlt Disziplin“ beschreibt die Bedingung nicht.","Studien, die ein gewünschtes Ergebnis mit einem echten Hindernis und einer Wenn-dann-Reaktion verbanden, fanden im Durchschnitt kleine Vorteile. Sie belegten nicht, dass Unbehagen die Wirkung erklärt. Geld, Sorgearbeit, Zeit und Zugang sind Bedingungen, keine Glaubensfehler. Probiere eine Änderung: eine kleinere Aufgabe, eine freie Gelegenheit oder eine konkrete Bitte um Hilfe. Eine Bitte zählt als Fragen, nicht als erhaltene Hilfe."],example:{title:"Daniel sucht eine andere Gelegenheit",text:"Daniel wollte nach dem Abendessen seinen Lebenslauf bearbeiten. Seine Tochter brauchte aber den gemeinsamen Laptop für Hausaufgaben. Er notiert den Konflikt. Er fragt, ob er ihn morgen zehn Minuten vor dem Abendessen nutzen kann. Sie einigen sich. Dann verbessert er einen Satz und hört auf. Die Bewerbung ist noch nicht fertig."}},move:{invitation:"Brauchst du Zugang? Wähle „Diesen Schritt anpassen“, dann „Unterstützung“. Benenne deine Kontaktperson. Die Vorschläge zeigen Daniels Bitte um Laptopzeit.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei, wenn der Zugang bereits abgesprochen ist.","Ohne Zugang: Benenne Person, Hilfsmittel und Gelegenheit in deiner Bitte um Unterstützung.","Halte die Bitte getrennt von erhaltener Hilfe und erledigter Arbeit fest."],prompts:[],suggestions:{action:["Tochter um Laptopzeit vor dem Abendessen bitten","In der Bibliothek nach freier Computerzeit fragen"],minimum:["Tochter um zehn Minuten am Laptop bitten","Die Frage nach Computerzugang in der Bibliothek abschicken"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn wir die Hausaufgaben zu Hause besprechen","Nach dem Mittagessen heute","Wenn das Abendessen abgeräumt ist"],place:["An meinem Küchentisch","Im Kontaktformular der Bibliothek","Am Schreibtisch in der Bibliothek"],minutes:[5,2,10],fallback:["In der Bibliothek nach Computerzugang fragen","Jemanden zu Hause um die Laptopzeit bitten","Pausieren, bis eine machbare Gelegenheit abgesprochen ist"],observation:["Die Bitte um Zugang und eine mögliche Antwort","Ob wir die Laptopzeit tatsächlich abgesprochen haben","Ob ich den gewählten Lebenslaufsatz überarbeitet habe"]},suggested:{action:"Tochter um Laptopzeit vor dem Abendessen bitten",minimum:"Tochter um zehn Minuten am Laptop bitten",minutes:5,cueHint:"Wenn wir die Hausaufgaben zu Hause besprechen",placeHint:"An meinem Küchentisch",obstacleHint:"Meine Tochter kann mir keine Laptopzeit anbieten",fallbackHint:"In der Bibliothek nach Computerzugang fragen",observationHint:"Die Bitte um Zugang und eine mögliche Antwort",kind:"support"},accessibleAlternative:"Tippe, sprich oder nutze Hilfe. Wähle „Diesen Schritt anpassen“ für die Aufgabe, sobald der Zugang abgesprochen ist.",stopRule:"Wenn die Übung dich überfordert oder die Umgebung unsicher ist, pausiere und suche passende Unterstützung."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Daniels abendliche Lebenslaufarbeit kollidiert mit Hausaufgaben am gemeinsamen Laptop. Zehn Minuten vor dem Abendessen wären frei, wenn beide sich darauf einigen.",question:"Welche Reaktion passt zu diesem Hindernis?",options:[{id:"manifest-3-arrange-opening",text:"Die freien zehn Minuten gemeinsam absprechen und dann einen Satz im selben Entwurf verbessern.",feedback:"Das ändert die Bedingung, die die Aufgabe blockiert hat, und behält ein sinnvolles Minimum bei. Eine Absprache ist noch nötig. Halte die Bitte getrennt fest, solange die Gelegenheit nicht bestätigt ist."},{id:"manifest-3-keep-evening",text:"Beim Abendtermin bleiben und länger im Kopf üben, damit er bereit ist, sobald der Laptop frei wird.",feedback:"Eine Probe kann den Wortlaut vorbereiten. Der Konflikt um den Zugang bleibt aber bestehen. Daniel hat eine mögliche andere Gelegenheit. Sprich sie erst ab, bevor du eine weitere Vorbereitung einbaust."},{id:"manifest-3-wait-week",text:"Warten, bis die Hausaufgaben nächste Woche weniger Zeit brauchen, und dann wie ursprünglich geplant länger am Lebenslauf arbeiten.",feedback:"Warten kann passen, wenn keine machbare Gelegenheit besteht. Hier lässt sich womöglich jetzt eine kleinere vereinbaren. Probiere das aus, statt die gesamte Arbeit automatisch auf später zu verschieben."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Benenne die blockierende Bedingung. Ändere die Aufgabe oder bitte um die Hilfe, die sie braucht.",followUp:{questionId:"manifest-3-return",question:"Hast du um Zugang gebeten oder an der Aufgabe gearbeitet? Welche Absprache steht noch aus?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Ein Hindernis liefert Informationen und muss nicht wehtun",paragraphs:["Die Übersichtsarbeit von 2021 zu mentalem Kontrastieren mit Planung fand über 24 unabhängige Effekte hinweg einen kleinen durchschnittlichen Vorteil bei der Zielerreichung. Deutliche Unterschiede und Hinweise auf Publikationsverzerrung begrenzen die Sicherheit. Unbehagen wurde nicht als wirksamer Bestandteil isoliert. Eine Schwierigkeit zu benennen kann unangenehm sein. Die Aufgabe besteht aber nicht darin, Belastung absichtlich zu verstärken. [M01]","In dem geprüften Verfahren von Oettingen und Kollegen aus 2015 beschrieben Studierende ein gewünschtes Ergebnis und ihr wichtigstes Hindernis ausführlich. Sie wählten eine Reaktion, verbanden Hindernis und Handlung in einem Plan und ergänzten übliche Zeit und Ort. In Studie 1 fiel der vorab geplante Vergleich bei im Kalender eingeplanten Stunden zugunsten der Methode aus. Gemessen wurde eingeplante Zeit, keine erledigte Arbeit. Der Gesamttest über die Bedingungen war nicht eindeutig. [M11] ODA ergänzt eine Prüfung praktischer Machbarkeit und einen tatsächlichen Versuch. Weder diese kürzere Übung noch ihre Trennung von äußeren Bedingungen und persönlichen Reaktionen wurde in dem Experiment eigens validiert."]},{heading:"Wann Unterstützung die passende Reaktion ist",paragraphs:["Trenne dein gewünschtes Ergebnis von den Bedingungen, die du dafür brauchst. Fehlt ein Hilfsmittel, brauchst du Zugang. Ist die Situation unsicher, brauchst du Schutz. Kollidiert die Aufgabe mit Sorgearbeit, brauchst du vielleicht eine andere Gelegenheit. Das ist eine Kursentscheidung, die sich an der Planungsforschung orientiert. Sie ist keine feste Einteilung, die jedes Hindernis genau einer Schublade zuweist. Eine Bitte um Unterstützung wird konkret, wenn du die benötigte Hilfe und die passende Gelegenheit benennst. [M01, M11]","Wenn jemand noch nicht geantwortet hat, halte die Bitte und die fehlende Antwort fest. Trage keine erhaltene Hilfe oder erledigte Arbeit ein. Du kannst einen anderen machbaren Schritt wählen, das Ziel ändern oder pausieren. Suche bei anhaltender Belastung oder erheblicher Beeinträchtigung fachliche Unterstützung, statt die Übung zu verstärken. Die NIMH-Orientierung zeigt Wege zu Behandlung und Krisenhilfe. Sie belegt nicht, dass ODA eine Erkrankung behandelt. [M14] Beschreibe im nächsten Eintrag die gewählte Handlung, auch Schutz oder Unterstützung. Mach aus dem ursprünglichen Hindernis keinen Mangel an Glauben."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"de",title:"Warte nicht länger auf die richtige Stimmung",goal:"Nutze ein erkennbares Startsignal und eine kleine Reaktion auf die beobachtete schwierige Stelle.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"„Wenn ich mich bereit fühle“ verschiebt sich. Wähle einen Moment, den du bemerkst.",reason:{id:"manifest-4-reason",label:"Was hat Aufschieben dich gekostet, als das Startsignal zuletzt kam?",kind:"text",maxLength:160,optional:!0,suggestions:["Beispiele verglichen; nicht zum Schreiben gekommen","Auf Bereitschaft gewartet; Entwurf blieb unverändert","Sorgearbeit war nötig; keine sichere Gelegenheit","Noch kein Startsignal; Wortwahl könnte mich aufhalten"],help:"Noch kein Versuch? Benenne ein mögliches Zögern."},why:{id:"manifest-4-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Startsignal und eine Reaktion auf ein Hindernis erfüllen verschiedene Aufgaben. „Wenn die Teller abgeräumt sind, schreibe ich einen Lebenslaufsatz“ schafft eine Gelegenheit. „Wenn ich hängen bleibe, beschreibe ich eine Schichtänderung“ hilft dir während dieser Gelegenheit weiter.","Studien mit unterschiedlichen Zielen fanden, dass konkrete Wenn-dann-Pläne im Durchschnitt beim Dranbleiben halfen. Erinnern, Anstrengung und praktische Hindernisse verschwinden dadurch nicht vollständig. Behalte deine Aufgabe bei. Reagiere auf ein Hindernis aus deinen Notizen, falls es eines gibt. Wähle ein erkennbares Signal und eine Reaktion, die du dort umsetzen kannst. Bleibt das Signal aus, halte die fehlende Gelegenheit fest und suche eine andere."],example:{title:"Daniel nutzt das Startsignal",text:"Daniel legt einen Zettel neben den gemeinsamen Laptop: „Wenn die Teller abgeräumt sind, verbessere einen Satz. Wenn du hängen bleibst, beschreibe eine Schichtänderung.“ Am Donnerstag kommt das Signal. Er bemerkt den Zettel und schreibt einen brauchbaren Satz. Den Abschnitt schafft er vor den nächsten Familienaufgaben nicht. Seine Notizen halten beide Tatsachen fest."}},move:{invitation:"Behalte deine Aufgabe und Gelegenheit bei. Die Vorschläge zeigen Daniels Lebenslaufbeispiel.",instructions:["Behalte Handlung, Minimum, Startsignal und Ort bei, sofern keines davon geändert werden muss.","Benenne vor dem Speichern die kleinere Reaktion auf deine tatsächliche schwierige Stelle."],prompts:[],suggestions:{action:["Nach dem Abendessen einen Satz zur Schichtplanung schreiben","Nach dem Mittagessen die Lebenslauffrage abschicken","Nach dem Tee ein Datum im Lebenslauf berichtigen"],minimum:["Einen Lebenslaufsatz zur Schichtplanung speichern","Die Frage zur fehlenden Lebenslaufangabe abschicken","Ein berichtigtes Datum im Lebenslauf speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn die Teller abgeräumt sind","Wenn die Mittagspause zu Ende ist","Wenn ich meinen Tee abstelle"],place:["An meinem Küchentisch","Im Dokument mit meinem Lebenslauf","Am Schreibtisch in der Bibliothek"],minutes:[5,2,10],fallback:["Eine Schichtänderung in einem Satz beschreiben","Eine andere freie Gelegenheit auswählen und benennen","In der Bibliothek nach Computerzugang fragen"],observation:["Ob das Startsignal kam und ich es bemerkte","Ob ich die Schichtänderung beschrieben habe","Die Lebenslaufänderung, die ich tatsächlich gespeichert habe"]},suggested:{action:"Nach dem Abendessen einen Satz zur Schichtplanung schreiben",minimum:"Einen Lebenslaufsatz zur Schichtplanung speichern",minutes:5,cueHint:"Wenn die Teller abgeräumt sind",placeHint:"An meinem Küchentisch",obstacleHint:"Ich bemerke das Startsignal, stocke aber beim Formulieren",fallbackHint:"Eine Schichtänderung in einem Satz beschreiben",observationHint:"Ob das Startsignal kam und ich es bemerkte"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Betreuungspflichten und Sicherheit gehen vor. Nutze eine andere Gelegenheit, wenn dieses Signal nicht mehr passt."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniel hat nach dem Abräumen fünf Minuten. Sein Entwurf und ein zutreffendes Beispiel einer Schichtänderung liegen bereit. Er stockt aber beim Formulieren.",question:"Welcher Plan hilft beim Anfangen und beim Stocken?",options:[{id:"manifest-4-mood-cue",text:"Wenn er nach dem Abendessen klarer denken kann, fünf Minuten am Lebenslaufabschnitt mit seinen besten Beispielen arbeiten.",feedback:"Ein klarerer Kopf wäre schön, ist aber ein wechselndes Startsignal. Nutze das erkennbare Ereignis nach dem Abendessen und eine Reaktion, die in die verfügbaren fünf Minuten passt."},{id:"manifest-4-full-section",text:"Nach dem Abräumen drei Beispiele für Schichtplanung vergleichen und erst dann das beste für den Lebenslaufsatz auswählen.",feedback:"Vergleichen kann bei der Auswahl helfen. Daniel hat aber bereits ein zutreffendes Beispiel. Die Suche würde seine fünf Minuten verbrauchen. Beschreibe zuerst diese Schichtänderung. Prüfe den Wortlaut, sobald ein echter Satz da ist."},{id:"manifest-4-cue-and-response",text:"Nach dem Abräumen einen Satz verbessern. Wenn er beim Formulieren stockt, eine tatsächliche Schichtänderung in einfachen Worten beschreiben.",feedback:"So haben der Start und die schwierige Stelle je eine passende Reaktion. Daniel kann es mit seinem fertigen Entwurf versuchen. Der Plan hilft bei einer Handlung, verspricht aber weder müheloses Erinnern noch einen fertigen Abschnitt."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Schaff eine Gelegenheit zum Anfangen und eine Antwort aufs Stocken. Prüfe dann, was wirklich passiert ist.",followUp:{questionId:"manifest-4-return",question:"Hast du das Startsignal bemerkt, und konntest du deine geplante Reaktion nutzen?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Wobei konkrete Planung helfen kann",paragraphs:["Gollwitzer und Sheerans Kapitel von 2006 fasste 94 unabhängige Tests mit 8.461 Teilnehmenden zusammen. Wenn-dann-Pläne zeigten im Durchschnitt einen Effekt auf die Zielerreichung von d = 0,65, mit einem 95%-Konfidenzintervall von 0,60 bis 0,70. Aufgaben und Verfahren waren unterschiedlich. Diese älteren Studien waren nicht durchgängig vorab registriert. Sie belegen nicht, dass jeder selbst geschriebene Satz wirkt. [M02]","Im Experiment zur Gelegenheitsplanung wählten Studierende eine konkrete Zeit und einen Ort, um mit einem Bericht anzufangen. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende, nicht alle Personen mit dieser Aufgabe. [M10] Daraus folgt weniger als „Ein Plan ersetzt Willenskraft“. Entscheide deine Reaktion vorher. Prüfe dann, ob die Situation eintrat, du sie bemerkt hast und die Reaktion passte. Behalte äußere Erinnerungen, wenn du sie brauchst. Ein Zettel neben einem Hilfsmittel ist eine ODA-Option. Dass du damit das Signal sicher bemerkst, ist wissenschaftlich nicht belegt."]},{heading:"Zwei Aufgaben, ein fortlaufender Versuch",paragraphs:["Deine geplante Gelegenheit beantwortet, wann du die Aufgabe angehst. Deine Reaktion auf ein Hindernis beantwortet, was du bei einer beobachteten Schwierigkeit tust. Das geprüfte Verfahren zum mentalen Kontrastieren verband ein Hindernis mit einer Reaktion und ergänzte die übliche Zeit und den Ort. Es belegte nicht, dass jeder zwei getrennte Regeln braucht. [M11] Dieser Kurs unterscheidet ihre Aufgaben, damit du besser erkennen kannst, wo dein bisheriger Versuch stockt.","Angenommen, die geplante Gelegenheit entsteht gar nicht. Dann kannst du nicht sagen, dass deine Reaktion auf das Hindernis gescheitert ist. Kommt die Gelegenheit und du verpasst sie, ändere Signal oder Erinnerung. Bemerkst du sie, aber die Reaktion ist zu groß, verkleinere den nächsten sinnvollen Aufgabenteil. Das sind Möglichkeiten zum Ausprobieren. Ein privates Protokoll beweist sie nicht. Lass frühere Einträge mit ihrem ursprünglichen Minimum verbunden. Ein anderer nächster Plan macht einen unvollständigen alten Versuch nicht nachträglich fertig. Prüfe deine tatsächliche Handlung. Unterstützung, Erholung, Pausieren und ein anderes Ziel bleiben mögliche Entscheidungen."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"de",title:"Noch kein Ergebnis? Schau auf deine tatsächlichen Versuche",goal:"Nutze deine bisherigen Einträge, um einen machbaren nächsten Schritt und den Rückblick für nächste Woche zu wählen.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Bevor du den Traum aufgibst: Hast du den Weg ausprobiert oder bisher immer nur geplant?",reason:{id:"manifest-5-reason",label:"Was würde dich überzeugen, diesen Weg beizubehalten, zu ändern oder aufzugeben?",kind:"text",maxLength:160,optional:!0,suggestions:["Brauchbarer Entwurf; Bewerbung abschicken","Wiederholte Terminkonflikte; andere Gelegenheit wählen","Konkrete Rückmeldung; den unklaren Satz überarbeiten","Noch kein Versuch; ersten Test auswählen"]},why:{id:"manifest-5-purpose",label:"Was würde dir dieser Schritt in deiner Woche ermöglichen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Lies die Einträge zu demselben Ziel. Trenne, was du geplant, im Kopf geübt, tatsächlich getan und von anderen erhalten hast. Ein gespeicherter Entwurf belegt Arbeit am Entwurf. Er belegt weder eine abgeschickte Bewerbung noch das Interesse eines Arbeitgebers.","Eine Übersichtsarbeit über 138 Experimente fand im Durchschnitt Vorteile, wenn Fortschritte häufiger beobachtet wurden. Dieses genaue Protokoll und ein idealer Rhythmus für Rückblicke wurden nicht geprüft. Wähle anhand deiner Tatsachen: einen machbaren Schritt wiederholen, ein Problem ändern, Rückmeldung suchen oder ein ungeeignetes Ziel aufgeben. Gibt es keinen Versuch, benenne diese Lücke und erarbeite deinen ersten brauchbaren Teil."],example:{title:"Daniel plant die nächste Woche",text:"Daniel liest drei datierte Änderungen und eine ungenutzte Gelegenheit am Laptop. Sein Lebenslauf ist klarer, aber er hat noch keine Bewerbung abgeschickt. Er wählt eine passende Stelle, prüft ihre Anforderungen und schickt am Freitag die vorbereitete Fassung ab. Er notiert den Versand und plant einen Rückblick nächste Woche. Noch keine Antwort."}},move:{invitation:"Behalte, was passt. Benenne die nächste Handlung. Beispiel: eine fertige Bewerbung.",instructions:["Beim Wiederholen: Behalte Minimum und Termin bei. Ändere nur den beobachteten Engpass.","Ohne Eintrag: Benenne vor dem Speichern eine erste Handlung und das passende Minimum.","Nach Informationen zu fragen zählt als Fragen, nicht als Erledigen der blockierten Aufgabe."],prompts:[],suggestions:{action:["Die fertige Bewerbung für die gewählte Stelle abschicken","Kontaktperson nach einer unklaren Anforderung fragen","Einen Lebenslaufsatz anhand einer Rückmeldung überarbeiten"],minimum:["Die fertige Bewerbung einmal abschicken","Die Frage zur Bewerbungsanforderung abschicken","Den überarbeiteten Lebenslaufsatz speichern"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In zwei Tagen",daysFromToday:2}],cue:["Wenn die Mittagspause zu Ende ist","Wenn das Abendessen abgeräumt ist","Wenn ich die Bewerbungsseite der Stelle öffne"],place:["An meinem Küchentisch","Am Schreibtisch in der Bibliothek","Im Bewerbungsformular für diese Stelle"],minutes:[10,2,5],fallback:["Die Kontaktperson nach der unklaren Anforderung fragen","Um Rückmeldung zum unklaren Satz bitten","Pausieren, bis die nötige Information vorliegt"],observation:["Den Versand und eine Bestätigung, falls vorhanden","Die Informationsfrage und eine noch ausstehende Antwort","Was weiterhin außerhalb meiner Kontrolle liegt"]},suggested:{action:"Die fertige Bewerbung für die gewählte Stelle abschicken",minimum:"Die fertige Bewerbung einmal abschicken",minutes:10,cueHint:"Wenn die Mittagspause zu Ende ist",placeHint:"An meinem Küchentisch",obstacleHint:"Eine nötige Angabe für die Bewerbung ist unklar",fallbackHint:"Die Kontaktperson nach der unklaren Anforderung fragen",observationHint:"Den Versand und eine Bestätigung, falls vorhanden"},accessibleAlternative:"Tippe, diktiere oder nutze deine gewohnten Hilfsmittel. Bitte bei Bedarf um praktische Hilfe.",stopRule:"Gib nicht mehr Geld aus und verzichte nicht auf nötige Versorgung, um ein unsicheres Ergebnis zu erzwingen."},result:{question:"Hast du dein gewähltes Minimum erledigt?",observationPrompt:"Was hast du tatsächlich getan oder erarbeitet?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniel hat seinen Lebenslauf überarbeitet, aber sich noch nicht beworben. Die Bewerbungsfrist für eine passende Stelle endet heute Abend. Sein Entwurf erfüllt die Anforderungen. Morgen könnte jemand die Fassungen vergleichen.",question:"Wozu sollte sein Rückblick ihn führen?",options:[{id:"manifest-5-next-application",text:"Die fertige Bewerbung abschicken, den Versand festhalten und später zurückblicken, während die Antwort noch offen ist.",feedback:"Die Einträge zeigen einen konkreten nächsten Schritt, der bereitliegt und in Daniels Hand liegt. Die Handlung ist das Abschicken. Die Entscheidung des Arbeitgebers bleibt unbekannt, bis eine tatsächliche Rückmeldung kommt."},{id:"manifest-5-double-editing",text:"Vor dem Abschicken jemanden um einen Vergleich zweier Lebenslauffassungen bitten, damit schwache Formulierungen möglichst auffallen.",feedback:"Ein Vergleich könnte Qualitätsprobleme zeigen, kommt aber nach der heutigen Frist. Daniel hat die Anforderungen geprüft und kennt keine verbleibende Lücke. Schick diese passende Fassung ab. Nutze spätere Rückmeldung für eine konkrete Änderung."},{id:"manifest-5-change-direction",text:"Die Gelegenheit für mehrere weniger gezielte Bewerbungen nutzen. So die Reichweite erhöhen und erst später die Lebenslauffassung auswählen.",feedback:"Mehr Reichweite kann Chancen eröffnen. Hier ist eine passende Bewerbung schon fertig. Sie abzuschicken prüft diese konkrete Passung. Mehr Bewerbungen können später folgen, ohne diesen vorbereiteten, gezielten Versand zu ersetzen."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Lass deine Einträge den nächsten Schritt verändern. Einsatz, Vorbereitung und äußere Ergebnisse sagen Unterschiedliches aus.",followUp:{questionId:"manifest-5-return",question:"Was ist mit deiner Aufgabe oder Informationsfrage passiert, und was steht weiterhin aus?",observationPrompt:"Was ist bei deiner geplanten Gelegenheit passiert?",adjustmentPrompt:"Welche einzelne Änderung passt zu deiner nächsten Gelegenheit?"}},goDeeper:{sections:[{heading:"Fortschritte festhalten hilft bei einer Entscheidung",paragraphs:["Harkin und Kollegen untersuchten 2016 in ihrer Übersichtsarbeit 138 Experimente mit zufälliger Zuteilung und insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen. Sie ergab d = 0,40, mit einem 95%-Konfidenzintervall von 0,32 bis 0,48. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien lieferte eine niedrigere Schätzung. Interventionen, Ziele und Aufzeichnungsweisen unterschieden sich. Die Übersichtsarbeit prüfte weder ODAs Zusammenfassung noch die Karte für den nächsten Tag. [M03]","Über die Studien hinweg gingen schriftlich oder öffentlich berichtete Fortschritte mit größeren Effekten einher. Diese Vergleiche von Studienmerkmalen belegen weder, dass öffentliches Teilen nötig ist, noch dass ein bestimmtes App-Format den Nutzen verursacht. Behalte persönliche Angaben für dich, wenn das zu deiner Situation passt. Vergleiche anhand deiner Einträge, was der Plan verlangte und was du tatsächlich berichtet hast. Ohne Eintrag bleibt das Geschehen unbekannt. Erledigte Vorbereitung, eine unbeantwortete Bitte oder ein gestoppter Versuch behalten jeweils ihre eigene Bezeichnung. So lässt sich deine nächste Entscheidung prüfen, ohne dass du eine positive Geschichte liefern musst."]},{heading:"Plane die nächste Woche, ohne die vorige umzuschreiben",paragraphs:["Ein kurzes privates Protokoll kann ein Muster nahelegen. Es beweist aber nicht, warum ein äußeres Ergebnis eingetreten ist. Bewerbungen, Bestellungen und Antworten anderer können von Qualität, Zeitpunkt, Mitteln oder Umständen abhängen, die dein Protokoll nicht erfasst. Forschung zum Beobachten von Fortschritten stützt die Nutzung von Informationen. Sie legt keine allgemeingültige Anzahl von Versuchen fest, bevor du ein Ziel ändern solltest. [M03] Lass diese Unsicherheit beim Rückblick sichtbar.","Wähle eine machbare nächste Gelegenheit und einen Rückblicktermin für die kommende Woche. Behalte dein brauchbares Minimum und das, was dir Zugang zur Aufgabe verschafft hat. Ändere den Teil, den deine Einträge tatsächlich infrage stellen. Ist kein Versuch erfasst, berichte bekannte Tatsachen oder behandle die nächste kleine Handlung als deinen ersten Versuch. Erfinde keine geleistete Arbeit. Planungsstudien zeigen durchschnittliche Vorteile mit Unterschieden, keine garantierten Ergebnisse. [M01] Pausieren, Rückmeldung erbitten, praktische Unterstützung suchen oder eine andere Richtung wählen kann eine bewusste Entscheidung aus dem Rückblick sein. Behalte den früheren Eintrag, damit der Grund sichtbar bleibt."]}],sourceIds:["M03","M01"]}}],i={lang:"de",id:"manifest",title:"Dein Traum wartet? Fang konkret an",subtitle:"Fünf Lektionen. Erarbeite einen brauchbaren Anfang, probiere deine Reaktion auf Hindernisse aus und wähle anhand echter Einträge den nächsten Schritt.",description:"Mach aus einem selbst gewählten Wunsch brauchbare Arbeit. Übe zum Anfangen, ändere tatsächliche Bedingungen und prüfe denselben Versuch weiter.",scope:"Manifestieren bedeutet hier: Absicht, Vorbereitung und Handlung. Der Kurs behauptet nicht, dass Gedanken Ereignisse durch Quanteneffekte steuern, das Universum deine Wünsche liefert oder jeder Wunsch sicher wahr wird. Er bietet keine finanzielle, medizinische oder psychologische Beratung.",outcome:"Ein bedeutsames Ziel mit einem brauchbaren Minimum, ehrlichen Einträgen zu Versuchen und einem machbaren Plan für nächste Woche.",photo:{id:"1676782778930-11b311ec5134",alt:"Ein Feldweg führt über einen grünen Hügel zu fernen Bergen"},lessons:[{id:"manifest-1",v2:e[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Eine Hand schreibt eine Aufgabenliste in ein Notizbuch"},schemaVersion:2,title:"Dein Traum wartet? Mach heute etwas Brauchbares",minutes:6,goal:"Erarbeite einen brauchbaren Teil für ein Ziel, das du selbst wählst.",reading:["Ein besserer Job ist ein Ergebnis. Einen Satz im Lebenslauf zu verbessern ist eine Handlung. Ob jemand dich anruft, entscheiden weiterhin andere. Mach etwas, das sich lohnt. Miss deinen Einsatz nicht an der erhofften Antwort.","In einem Experiment mit Studierenden half ein festgelegter Start mit Zeit und Ort, einen Bericht rechtzeitig zu schreiben. Das galt für jene, die ihn zurückschickten. Die Mitarbeit insgesamt nahm nicht zu. Ein Plan kann beim Anfangen helfen, garantiert aber kein Ergebnis. Erarbeite heute einen brauchbaren Satz, eine Antwort oder eine Bitte. Bleib im Kurs bei diesem Ziel und komm mit dem zurück, was passiert ist."],practice:["Formuliere einen Wunsch, der dir wichtig ist, in einem Satz. Schreiben bleibt freiwillig.","Wähle eine Handlung, die in deiner Hand liegt und dich diesem Wunsch näherbringt.","Lege fest, wann der kleine Schritt erledigt ist, etwa nach „drei Sätzen eines Entwurfs“."],reflection:"Wie sieht dein Wunsch heute als konkrete Handlung aus?",question:"Welche dieser Handlungen kannst du direkt selbst wählen?",options:["Der Arbeitgeber entscheidet sich auf jeden Fall für mich.","Morgen drei Sätze in meinem Lebenslauf überarbeiten.","Es geht überhaupt nichts schief."],correct:1,feedback:"Die Entscheidungen anderer kannst du nicht garantieren. Deine eigene Vorbereitung kannst du konkret machen.",takeaway:"Mach aus dem Wunsch eine Handlung. Halte sie getrennt von der erhofften Antwort fest.",sources:["M10","M01","M07"],deeper:[{heading:"Wobei ein Plan zum Anfangen helfen kann",paragraphs:["In ihrer Studie 2 von 1997 ließen Gollwitzer und Brandstätter 86 Münchner Studierende einen Bericht über Weihnachten schreiben. Die Planungsgruppe wählte eine genaue Zeit und einen Ort, stellte sich diese Gelegenheit vor, nahm sich vor, dort anzufangen, und hielt die Entscheidungen fest. Von 36 eindeutig zuordenbaren Rücksendenden schrieben 12 von 17 mit Plan und sechs von 19 in der Kontrollgruppe innerhalb der geforderten zwei Tage. Diese Anteile betreffen die Rücksendenden, nicht alle aufgenommenen Personen. Planung erhöhte die Mitarbeit insgesamt nicht. [M10]","Diese Lektion übernimmt die konkrete Gelegenheit und verbindet sie mit brauchbarer Arbeit. Diese Übertragung auf andere Aufgaben wurde in der Weihnachtsbericht-Studie nicht geprüft. Ein Datum allein sagt dir noch nicht, woher die Zeit kommen soll. Wähle ein Ereignis, das du erkennst, und einen Ort, den du erreichen kannst. Fehlen nötige Mittel, kann es der passende Schritt sein, danach zu fragen. Halte diese Bitte als Bitte fest, auch wenn die Hilfe noch nicht da ist."]},{heading:"Dein Wunsch steuert keine anderen Menschen",paragraphs:["Wang und Kollegen fassten 2021 in einer Übersichtsarbeit 24 unabhängige Effekte aus 21 Artikeln mit 15.907 Teilnehmenden zusammen. Ein gewünschtes Ergebnis mit einem Hindernis und einer Wenn-dann-Reaktion zu verbinden, brachte im Durchschnitt einen kleinen Vorteil bei der Zielerreichung: g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Die Ergebnisse unterschieden sich deutlich. Eine Korrektur möglicher Publikationsverzerrung senkte die Schätzung. Das stützt Planung innerhalb ihrer Grenzen, aber kein Erfolgsversprechen für diesen Kurs. [M01]","Dixon und Kollegen untersuchten Manifestationsglauben in drei US-Onlinebefragungen mit insgesamt 1.023 Teilnehmenden. Er hing mit einigen selbst berichteten finanziellen Risiken und Insolvenzen zusammen, nicht mit selbst berichtetem Einkommen oder Bildungsstand. Diese Zusammenhänge belegen nicht, dass der Glaube Insolvenzen verursacht hat. Sie prüfen auch nicht jede Manifestationsübung objektiv. [M07] Nutze deinen Wunsch, um eine Aufgabe zu wählen und Grenzen zu prüfen. Schließe daraus nicht, dass Gedanken eine Gelegenheit angezogen oder Not verursacht haben. Du hast dir ein Ergebnis auch nicht durch Gedanken verdient. Geld, Sorgearbeit, Zugang und die Entscheidungen anderer bleiben relevant."]}],example:{title:"Daniel fängt an",text:"Nach dem Abendessen setzt Daniel sich für zehn Minuten an den Küchentisch. Er sucht einen Logistikjob. Im Lebenslauf beschreibt er neu, wie er acht Lagerschichten geplant hat. Der Satz klingt noch holprig. Trotzdem speichert er ihn und notiert die Änderung. Ein Arbeitgeber hat ihn noch nicht gesehen. Morgen kann Daniel einen echten Entwurf verbessern."}},{id:"manifest-2",v2:e[1],photo:{id:"1517363898874-737b62a7db91",alt:"Eine Person sitzt ruhig am Fenster im warmen Licht"},schemaVersion:2,title:"Wieder nur geübt? Bring den Satz aufs Papier",minutes:6,goal:"Übe eine schwierige Stelle im Kopf. Erarbeite dann den nächsten brauchbaren Teil deiner bisherigen Aufgabe.",reading:["Hol deine Aufgabe und vorhandene Notizen hervor. Im Kopf zu üben bedeutet, eine bestimmte Handlung gedanklich auszuführen, etwa den ersten Satz zu sagen. Schritte aufzulisten ist eine andere Art der Vorbereitung. Beides ist noch kein tatsächlicher Versuch.","Eine Übersichtsarbeit fand im Durchschnitt Vorteile für das Verhalten durch gedankliches Durchspielen. Eine beste Form war nicht belegt. Das beweist nicht, dass diese kurze Probe wirkt. Nutze sie, um deine schwierige Stelle und eine mögliche Reaktion zu erkennen. Beschreibe die Handlung in Worten, wenn keine Bilder kommen. Schreibe danach den nächsten brauchbaren Satz für dieselbe Aufgabe."],practice:["Benenne eine Veränderung, die dein Ziel in deinem Leben bewirken soll.","Ordne deine ersten beiden Schritte als Bilder oder in Worten.","Erledige nach der Probe tatsächlich einen Schritt der Vorbereitung."],reflection:"Welche fehlende Vorbereitung ist dir beim Üben aufgefallen?",question:"Was bedeutet es in diesem Kurs, im Kopf zu üben?",options:["Eine Übung, die mich auf eine tatsächliche Handlung vorbereitet.","Mit Gedanken äußere Ereignisse sicher steuern.","Gar nichts mehr ausprobieren müssen."],correct:0,feedback:"Im Kopf zu üben ist Vorbereitung. Die genannten Studien validieren diese kurze Übung nicht und zeigen nicht, dass sie äußere Ergebnisse steuert. Nutze Vorbereitung für eine tatsächliche Handlung.",takeaway:"Lass auf hilfreiche Vorbereitung eine echte Handlung folgen. Halte beides getrennt fest.",sources:["M04","M10"],deeper:[{heading:"Was sich aus der Forschung zum Durchspielen vergleichen lässt",paragraphs:["Cole und Kollegen fassten 2021 in einer Übersichtsarbeit 94 Studien, 123 Effekte und 5.685 Teilnehmende zusammen. Gedankliches Durchspielen zeigte insgesamt einen Verhaltenseffekt von g = 0,49, mit einem 95%-Konfidenzintervall von 0,37 bis 0,62. Meist waren die Teilnehmenden Studierende. Inhalt, Umfang und gemessene Ergebnisse der Übungen unterschieden sich. Der Durchschnitt sagt daher nicht voraus, was deine kurze Übung bewirkt. [M04]","Die Übersichtsarbeit unterschied zwischen dem Durchdenken von Ablaufschritten und dem gedanklichen Ausführen einer Aufgabe. Die Schätzung für reine Ablaufvorstellungen beruhte auf fünf Effekten; ihr Konfidenzintervall umfasste auch den Wert für keinen Effekt. Der Gesamtvergleich der Formen war statistisch nicht signifikant. Höhere Durchschnittswerte einzelner Gruppen belegen deshalb keinen verlässlichen Sieger. Eine Grafik ist kein Auftrag, intensiver zu visualisieren. Diese Lektion nutzt die Probe, um ein praktisches Detail sichtbar zu machen. Danach versuchst du die Aufgabe. Eine Beschreibung in Worten bietet einen zugänglichen Weg. Das bedeutet nicht, dass ihre Gleichwertigkeit mit Bildern wissenschaftlich belegt wäre."]},{heading:"Bereite eine Gelegenheit vor und nutze sie dann",paragraphs:["Im ursprünglichen Experiment zur Berichtsplanung stellten sich die Teilnehmenden eine konkrete Zeit und einen Ort zum Anfangen vor. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende und eine eng begrenzte Studienaufgabe. Daraus folgt weder ein allgemeines Vorstellungsskript noch ein Vorteil von Proben im Bett. [M10] Hier ist Vorbereitung dann sinnvoll, wenn sie dir beim nächsten Teil deiner bisherigen Aufgabe hilft.","Vielleicht bemerkst du ein fehlendes Passwort, eine unklare Anweisung oder einen Satz, den du noch nicht erklären kannst. Ein Passwort zurückzusetzen ist Vorbereitung. Benötigte Angaben abzusenden ist Arbeit an der Aufgabe. Zeig diesen Unterschied in deinen Notizen. Hör mit Planung vor dem Schlafen auf, wenn sie dich wach hält, und plane stattdessen tagsüber. Das ist eine praktische Anpassung für diesen Kurs. Die kurze Probe ist freiwillig. Sie ist weder ein validiertes Ritual noch eine Voraussetzung zum Anfangen. Du brauchst kein lebhaftes Bild und kein bestimmtes Gefühl."]}],example:{title:"Daniel vor der leeren Zeile",text:"Nach dem Abendessen öffnet Daniel seinen Lebenslauf wieder. Dreißig Sekunden lang übt er im Kopf, eine schwierige Schichtänderung zu beschreiben. Er erwartet, ins Stocken zu geraten, und probt: „Acht Schichten umgeplant, als …“ Dann tippt er einen brauchbaren Satz. Er streicht zwei Wörter und notiert eine Rückfrage. Wie viele Details nötig sind, hatte seine Probe nicht gezeigt."}},{id:"manifest-3",v2:e[2],photo:{id:"1767134063671-322e6faf9206",alt:"Ein umgestürzter Baum liegt quer über einem grünen Waldweg"},schemaVersion:2,title:"Das Hindernis ist echt. Ändere die Bedingungen",minutes:6,goal:"Nutze deinen letzten Versuch, um eine machbare Reaktion auf ein Hindernis zu wählen und auszuprobieren.",reading:["Nutze dein Ziel und vorhandene Notizen. Ohne Versuch: Benenne ein wahrscheinliches Hindernis. „Abends ist der gemeinsame Computer belegt“ hilft, eine Reaktion zu finden. „Mir fehlt Disziplin“ beschreibt die Bedingung nicht.","Studien, die ein gewünschtes Ergebnis mit einem echten Hindernis und einer Wenn-dann-Reaktion verbanden, fanden im Durchschnitt kleine Vorteile. Sie belegten nicht, dass Unbehagen die Wirkung erklärt. Geld, Sorgearbeit, Zeit und Zugang sind Bedingungen, keine Glaubensfehler. Probiere eine Änderung: eine kleinere Aufgabe, eine freie Gelegenheit oder eine konkrete Bitte um Hilfe. Eine Bitte zählt als Fragen, nicht als erhaltene Hilfe."],practice:["Benenne das nächste Hindernis, das deinem Ziel im Weg steht.","Trenne den beeinflussbaren Teil des Hindernisses von dem, für den du Unterstützung oder Zeit brauchst.","Geht es gerade nicht, verkleinere das Ziel oder verschiebe es auf eine passende Gelegenheit."],reflection:"Was hat sich in deinem Plan geändert, seit du das Hindernis realistischer betrachtest?",question:"Wenn äußere Bedingungen im Weg stehen …",options:["Sollte ich annehmen, dass ich nicht genug geglaubt habe.","Sollte ich diese Bedingungen ignorieren.","Kann ich Unterstützung, Zeitpunkt oder Größe des Ziels überdenken."],correct:2,feedback:"Ein realistischer Plan berücksichtigt äußere Bedingungen. Deine Gedanken entscheiden nicht allein über Ergebnisse.",takeaway:"Benenne die blockierende Bedingung. Ändere die Aufgabe oder bitte um die Hilfe, die sie braucht.",sources:["M01","M11","M14"],deeper:[{heading:"Ein Hindernis liefert Informationen und muss nicht wehtun",paragraphs:["Die Übersichtsarbeit von 2021 zu mentalem Kontrastieren mit Planung fand über 24 unabhängige Effekte hinweg einen kleinen durchschnittlichen Vorteil bei der Zielerreichung. Deutliche Unterschiede und Hinweise auf Publikationsverzerrung begrenzen die Sicherheit. Unbehagen wurde nicht als wirksamer Bestandteil isoliert. Eine Schwierigkeit zu benennen kann unangenehm sein. Die Aufgabe besteht aber nicht darin, Belastung absichtlich zu verstärken. [M01]","In dem geprüften Verfahren von Oettingen und Kollegen aus 2015 beschrieben Studierende ein gewünschtes Ergebnis und ihr wichtigstes Hindernis ausführlich. Sie wählten eine Reaktion, verbanden Hindernis und Handlung in einem Plan und ergänzten übliche Zeit und Ort. In Studie 1 fiel der vorab geplante Vergleich bei im Kalender eingeplanten Stunden zugunsten der Methode aus. Gemessen wurde eingeplante Zeit, keine erledigte Arbeit. Der Gesamttest über die Bedingungen war nicht eindeutig. [M11] ODA ergänzt eine Prüfung praktischer Machbarkeit und einen tatsächlichen Versuch. Weder diese kürzere Übung noch ihre Trennung von äußeren Bedingungen und persönlichen Reaktionen wurde in dem Experiment eigens validiert."]},{heading:"Wann Unterstützung die passende Reaktion ist",paragraphs:["Trenne dein gewünschtes Ergebnis von den Bedingungen, die du dafür brauchst. Fehlt ein Hilfsmittel, brauchst du Zugang. Ist die Situation unsicher, brauchst du Schutz. Kollidiert die Aufgabe mit Sorgearbeit, brauchst du vielleicht eine andere Gelegenheit. Das ist eine Kursentscheidung, die sich an der Planungsforschung orientiert. Sie ist keine feste Einteilung, die jedes Hindernis genau einer Schublade zuweist. Eine Bitte um Unterstützung wird konkret, wenn du die benötigte Hilfe und die passende Gelegenheit benennst. [M01, M11]","Wenn jemand noch nicht geantwortet hat, halte die Bitte und die fehlende Antwort fest. Trage keine erhaltene Hilfe oder erledigte Arbeit ein. Du kannst einen anderen machbaren Schritt wählen, das Ziel ändern oder pausieren. Suche bei anhaltender Belastung oder erheblicher Beeinträchtigung fachliche Unterstützung, statt die Übung zu verstärken. Die NIMH-Orientierung zeigt Wege zu Behandlung und Krisenhilfe. Sie belegt nicht, dass ODA eine Erkrankung behandelt. [M14] Beschreibe im nächsten Eintrag die gewählte Handlung, auch Schutz oder Unterstützung. Mach aus dem ursprünglichen Hindernis keinen Mangel an Glauben."]}],example:{title:"Daniel sucht eine andere Gelegenheit",text:"Daniel wollte nach dem Abendessen seinen Lebenslauf bearbeiten. Seine Tochter brauchte aber den gemeinsamen Laptop für Hausaufgaben. Er notiert den Konflikt. Er fragt, ob er ihn morgen zehn Minuten vor dem Abendessen nutzen kann. Sie einigen sich. Dann verbessert er einen Satz und hört auf. Die Bewerbung ist noch nicht fertig."}},{id:"manifest-4",v2:e[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Bunte Haftnotizen und Stifte"},schemaVersion:2,title:"Warte nicht länger auf die richtige Stimmung",minutes:6,goal:"Nutze ein erkennbares Startsignal und eine kleine Reaktion auf die beobachtete schwierige Stelle.",reading:["Ein Startsignal und eine Reaktion auf ein Hindernis erfüllen verschiedene Aufgaben. „Wenn die Teller abgeräumt sind, schreibe ich einen Lebenslaufsatz“ schafft eine Gelegenheit. „Wenn ich hängen bleibe, beschreibe ich eine Schichtänderung“ hilft dir während dieser Gelegenheit weiter.","Studien mit unterschiedlichen Zielen fanden, dass konkrete Wenn-dann-Pläne im Durchschnitt beim Dranbleiben halfen. Erinnern, Anstrengung und praktische Hindernisse verschwinden dadurch nicht vollständig. Behalte deine Aufgabe bei. Reagiere auf ein Hindernis aus deinen Notizen, falls es eines gibt. Wähle ein erkennbares Signal und eine Reaktion, die du dort umsetzen kannst. Bleibt das Signal aus, halte die fehlende Gelegenheit fest und suche eine andere."],practice:["Beschreibe ein erkennbares Hindernis mit „Wenn …“.","Schreibe nach „dann …“ eine einzige kleine Handlung auf.","Prüfe, ob der Plan zur verfügbaren Zeit und deinen Hilfsmitteln passt. Übe ihn dann einmal."],reflection:"Wie lautet dein Wenn-dann-Satz?",question:"Welchen Plan kannst du tatsächlich ausprobieren?",options:["Es wird sich alles von selbst regeln.","Wenn ich beim Öffnen der Datei stocke, schreibe ich zuerst den Titel.","Wenn ich gute Energie aussende, verschwinden alle Hindernisse."],correct:1,feedback:"Die zweite Antwort verbindet eine konkrete Situation mit einer beobachtbaren Handlung. Diese Art von Handlungsplanung ähnelt dem Vorgehen in den Studien.",takeaway:"Schaff eine Gelegenheit zum Anfangen und eine Antwort aufs Stocken. Prüfe dann, was wirklich passiert ist.",sources:["M02","M10","M11"],deeper:[{heading:"Wobei konkrete Planung helfen kann",paragraphs:["Gollwitzer und Sheerans Kapitel von 2006 fasste 94 unabhängige Tests mit 8.461 Teilnehmenden zusammen. Wenn-dann-Pläne zeigten im Durchschnitt einen Effekt auf die Zielerreichung von d = 0,65, mit einem 95%-Konfidenzintervall von 0,60 bis 0,70. Aufgaben und Verfahren waren unterschiedlich. Diese älteren Studien waren nicht durchgängig vorab registriert. Sie belegen nicht, dass jeder selbst geschriebene Satz wirkt. [M02]","Im Experiment zur Gelegenheitsplanung wählten Studierende eine konkrete Zeit und einen Ort, um mit einem Bericht anzufangen. Der Vergleich zur rechtzeitigen Bearbeitung betraf eindeutig zuordenbare Rücksendende, nicht alle Personen mit dieser Aufgabe. [M10] Daraus folgt weniger als „Ein Plan ersetzt Willenskraft“. Entscheide deine Reaktion vorher. Prüfe dann, ob die Situation eintrat, du sie bemerkt hast und die Reaktion passte. Behalte äußere Erinnerungen, wenn du sie brauchst. Ein Zettel neben einem Hilfsmittel ist eine ODA-Option. Dass du damit das Signal sicher bemerkst, ist wissenschaftlich nicht belegt."]},{heading:"Zwei Aufgaben, ein fortlaufender Versuch",paragraphs:["Deine geplante Gelegenheit beantwortet, wann du die Aufgabe angehst. Deine Reaktion auf ein Hindernis beantwortet, was du bei einer beobachteten Schwierigkeit tust. Das geprüfte Verfahren zum mentalen Kontrastieren verband ein Hindernis mit einer Reaktion und ergänzte die übliche Zeit und den Ort. Es belegte nicht, dass jeder zwei getrennte Regeln braucht. [M11] Dieser Kurs unterscheidet ihre Aufgaben, damit du besser erkennen kannst, wo dein bisheriger Versuch stockt.","Angenommen, die geplante Gelegenheit entsteht gar nicht. Dann kannst du nicht sagen, dass deine Reaktion auf das Hindernis gescheitert ist. Kommt die Gelegenheit und du verpasst sie, ändere Signal oder Erinnerung. Bemerkst du sie, aber die Reaktion ist zu groß, verkleinere den nächsten sinnvollen Aufgabenteil. Das sind Möglichkeiten zum Ausprobieren. Ein privates Protokoll beweist sie nicht. Lass frühere Einträge mit ihrem ursprünglichen Minimum verbunden. Ein anderer nächster Plan macht einen unvollständigen alten Versuch nicht nachträglich fertig. Prüfe deine tatsächliche Handlung. Unterstützung, Erholung, Pausieren und ein anderes Ziel bleiben mögliche Entscheidungen."]}],example:{title:"Daniel nutzt das Startsignal",text:"Daniel legt einen Zettel neben den gemeinsamen Laptop: „Wenn die Teller abgeräumt sind, verbessere einen Satz. Wenn du hängen bleibst, beschreibe eine Schichtänderung.“ Am Donnerstag kommt das Signal. Er bemerkt den Zettel und schreibt einen brauchbaren Satz. Den Abschnitt schafft er vor den nächsten Familienaufgaben nicht. Seine Notizen halten beide Tatsachen fest."}},{id:"manifest-5",v2:e[4],photo:{id:"1762920738995-f393efe82205",alt:"Ein hölzerner Wegweiser zeigt im Wald in mehrere Richtungen"},schemaVersion:2,title:"Noch kein Ergebnis? Schau auf deine tatsächlichen Versuche",minutes:6,goal:"Nutze deine bisherigen Einträge, um einen machbaren nächsten Schritt und den Rückblick für nächste Woche zu wählen.",reading:["Lies die Einträge zu demselben Ziel. Trenne, was du geplant, im Kopf geübt, tatsächlich getan und von anderen erhalten hast. Ein gespeicherter Entwurf belegt Arbeit am Entwurf. Er belegt weder eine abgeschickte Bewerbung noch das Interesse eines Arbeitgebers.","Eine Übersichtsarbeit über 138 Experimente fand im Durchschnitt Vorteile, wenn Fortschritte häufiger beobachtet wurden. Dieses genaue Protokoll und ein idealer Rhythmus für Rückblicke wurden nicht geprüft. Wähle anhand deiner Tatsachen: einen machbaren Schritt wiederholen, ein Problem ändern, Rückmeldung suchen oder ein ungeeignetes Ziel aufgeben. Gibt es keinen Versuch, benenne diese Lücke und erarbeite deinen ersten brauchbaren Teil."],practice:["Mach deinen ersten kleinen Versuch oder lege genau fest, wann du ihn machst.","Wähle einen sinnvollen Rückblicktermin. Nutze die Fragen: „Was habe ich versucht, und was habe ich gelernt?“","Wähle, was passt: weitermachen, verkleinern, Unterstützung suchen oder das Ziel ändern."],reflection:"An welchem Tag und anhand welcher Informationen prüfst du deinen Plan?",question:"Welcher Rückblick hilft am meisten, wenn dein gewünschtes Ergebnis ausbleibt?",options:["Meine Gedanken waren nicht stark genug.","Meine versuchten Handlungen und die Bedingungen prüfen und dann die nächste Entscheidung treffen.","An derselben Erwartung festhalten, ohne auf die Wirklichkeit zu schauen."],correct:1,feedback:"Der Vergleich von Plan und Wirklichkeit liefert neue Informationen. Kein Kurs garantiert Ergebnisse. Du kannst deinen eigenen Anteil und die äußeren Bedingungen zusammen abwägen.",takeaway:"Lass deine Einträge den nächsten Schritt verändern. Einsatz, Vorbereitung und äußere Ergebnisse sagen Unterschiedliches aus.",sources:["M03","M01"],deeper:[{heading:"Fortschritte festhalten hilft bei einer Entscheidung",paragraphs:["Harkin und Kollegen untersuchten 2016 in ihrer Übersichtsarbeit 138 Experimente mit zufälliger Zuteilung und insgesamt 19.951 Teilnehmenden. Die Analyse zur Zielerreichung umfasste 18.398 Personen. Sie ergab d = 0,40, mit einem 95%-Konfidenzintervall von 0,32 bis 0,48. Eine Zusatzanalyse zu Verzerrungen durch kleine Studien lieferte eine niedrigere Schätzung. Interventionen, Ziele und Aufzeichnungsweisen unterschieden sich. Die Übersichtsarbeit prüfte weder ODAs Zusammenfassung noch die Karte für den nächsten Tag. [M03]","Über die Studien hinweg gingen schriftlich oder öffentlich berichtete Fortschritte mit größeren Effekten einher. Diese Vergleiche von Studienmerkmalen belegen weder, dass öffentliches Teilen nötig ist, noch dass ein bestimmtes App-Format den Nutzen verursacht. Behalte persönliche Angaben für dich, wenn das zu deiner Situation passt. Vergleiche anhand deiner Einträge, was der Plan verlangte und was du tatsächlich berichtet hast. Ohne Eintrag bleibt das Geschehen unbekannt. Erledigte Vorbereitung, eine unbeantwortete Bitte oder ein gestoppter Versuch behalten jeweils ihre eigene Bezeichnung. So lässt sich deine nächste Entscheidung prüfen, ohne dass du eine positive Geschichte liefern musst."]},{heading:"Plane die nächste Woche, ohne die vorige umzuschreiben",paragraphs:["Ein kurzes privates Protokoll kann ein Muster nahelegen. Es beweist aber nicht, warum ein äußeres Ergebnis eingetreten ist. Bewerbungen, Bestellungen und Antworten anderer können von Qualität, Zeitpunkt, Mitteln oder Umständen abhängen, die dein Protokoll nicht erfasst. Forschung zum Beobachten von Fortschritten stützt die Nutzung von Informationen. Sie legt keine allgemeingültige Anzahl von Versuchen fest, bevor du ein Ziel ändern solltest. [M03] Lass diese Unsicherheit beim Rückblick sichtbar.","Wähle eine machbare nächste Gelegenheit und einen Rückblicktermin für die kommende Woche. Behalte dein brauchbares Minimum und das, was dir Zugang zur Aufgabe verschafft hat. Ändere den Teil, den deine Einträge tatsächlich infrage stellen. Ist kein Versuch erfasst, berichte bekannte Tatsachen oder behandle die nächste kleine Handlung als deinen ersten Versuch. Erfinde keine geleistete Arbeit. Planungsstudien zeigen durchschnittliche Vorteile mit Unterschieden, keine garantierten Ergebnisse. [M01] Pausieren, Rückmeldung erbitten, praktische Unterstützung suchen oder eine andere Richtung wählen kann eine bewusste Entscheidung aus dem Rückblick sein. Behalte den früheren Eintrag, damit der Grund sichtbar bleibt."]}],example:{title:"Daniel plant die nächste Woche",text:"Daniel liest drei datierte Änderungen und eine ungenutzte Gelegenheit am Laptop. Sein Lebenslauf ist klarer, aber er hat noch keine Bewerbung abgeschickt. Er wählt eine passende Stelle, prüft ihre Anforderungen und schickt am Freitag die vorbereitete Fassung ab. Er notiert den Versand und plant einen Rückblick nächste Woche. Noch keine Antwort."}}]},t=Object.freeze(Object.defineProperty({__proto__:null,COURSE:i,MANIFEST_LESSONS_V2:e,SOURCES:n},Symbol.toStringTag,{value:"Module"}));export{t as m};
